// Engagement APIs (RegistrationManager, InboxMessageManager, AnalyticsManager, RegionMessageManager, sdkState):
MarketingCloudSdk.requestSdk { sdk ->
    // sdk is a MarketingCloudSdk — the same type name as legacy, still shipped by the engagement module.
    val current = sdk.sdkState.optJSONObject("RegistrationManager")
    sdk.analyticsManager.enableAnalytics()
}

// Push APIs (token, handleMessage): NOT reached through MarketingCloudSdk.requestSdk anymore —
// use PushFeature.requestSdk instead.
PushFeature.requestSdk { pushFeature ->
    pushFeature.getPushMessageManager().setPushToken(newToken)
}

// Legal — engagement module still supports tags:
MarketingCloudSdk.requestSdk { sdk ->
    sdk.registrationManager.edit().addTag("Camping").commit()
}
// OR (Salesforce guidance) — migrate to a profile attribute on unified identity:
SFMCSdk.requestSdk { it.identity.edit { attributes.set("segment", "Camping") } }

// Preferred (unified typed Event model):
EventManager.customEvent(
    "ProductDetail",
    mapOf("description" to "Product viewed")
)?.let { SFMCSdk.track(it) }

// Also still legal (analyticsManager remains on the engagement module):
MarketingCloudSdk.requestSdk { sdk ->
    sdk.analyticsManager.trackPageView("data://ProductDetail", "Product viewed")
}

// PREFERRED — register the listener at init inside InAppMessagingFeatureConfig:
inAppMessagingFeatureModuleConfig = InAppMessagingFeatureConfig.builder()
    .setEventListener(myListener)
    .build()

// RUNTIME ALTERNATIVE — setInAppMessageListener still exists; only the receiver moved:
InAppMessagingFeature.requestSdk { iamFeature ->
    iamFeature.getInAppMessageManager().setInAppMessageListener(myListener)  // listener is nullable; null clears it
}

